/// The `type` of an operation.
#[derive(Clone, Copy)]
pub(crate) enum OperationKind {
    Create,
    Set,
    Insert,
    Delete,
    Focus,
    ScrollTo,
    ScrollIntoView,
}

pub(crate) const OPERATION_KINDS: &[&str] = &[
    "create",
    "set",
    "insert",
    "delete",
    "focus",
    "scroll_to",
    "scroll_into_view",
];

impl OperationKind {
    pub(crate) fn from_name(name: &str) -> Option<Self> {
        Some(match name {
            "create" => Self::Create,
            "set" => Self::Set,
            "insert" => Self::Insert,
            "delete" => Self::Delete,
            "focus" => Self::Focus,
            "scroll_to" => Self::ScrollTo,
            "scroll_into_view" => Self::ScrollIntoView,
            _ => return None,
        })
    }

    /// One bit per [`OperationMember`] this kind accepts, `type` included.
    pub(crate) const fn members(self) -> u32 {
        match self {
            Self::Create => 0b111,
            Self::Set => 0b1111,
            Self::Insert => 0b1110001,
            Self::Delete => 0b11,
            Self::Focus => 0b11,
            Self::ScrollTo => 0b110000011,
            Self::ScrollIntoView => 0b11,
        }
    }

    /// The member names this kind accepts, for error messages.
    pub(crate) const fn member_names(self) -> &'static [&'static str] {
        match self {
            Self::Create => &["type", "node_id", "element"],
            Self::Set => &["type", "node_id", "element", "expected_input_revision"],
            Self::Insert => &["type", "parent_id", "child_id", "index"],
            Self::Delete => &["type", "node_id"],
            Self::Focus => &["type", "node_id"],
            Self::ScrollTo => &["type", "node_id", "x", "y"],
            Self::ScrollIntoView => &["type", "node_id"],
        }
    }
}

